#!/usr/bin/env node
/**
 * Copies the Quran reference (engine + slim dataset) from ../quran-reference — the ONE authoritative
 * source — into src/quran-reference/generated/. Never edit the generated files by hand: change
 * quran-reference/ and run `npm run quran:sync`. src/quran-reference/quran-reference.sync.spec.ts
 * fails when the copy drifts from the source.
 *
 * The backend build and the Docker image only contain backend/, hence a generated copy instead of a
 * runtime import.
 */
import { createHash } from 'node:crypto';
import { readFileSync, writeFileSync, mkdirSync } from 'node:fs';
import { dirname, join } from 'node:path';
import { fileURLToPath } from 'node:url';

const here = dirname(fileURLToPath(import.meta.url));
const SOURCE = join(here, '..', '..', 'quran-reference');
const TARGET = join(here, '..', 'src', 'quran-reference', 'generated');
const EDITIONS = [{ file: 'qalun-tn-v1.json', constant: 'QALUN_TN_V1' }];

const sha256 = (text) => createHash('sha256').update(text).digest('hex');
const HEADER = (from) =>
  `// GENERATED by backend/scripts/sync-quran-reference.mjs from quran-reference/${from} — do not edit.\n` +
  `/* eslint-disable */\n`;

/** The generated files, as { path: content } (also used by the drift test). */
export function render() {
  const out = {};
  for (const name of ['types.ts', 'engine.ts']) {
    const src = readFileSync(join(SOURCE, 'engine', name), 'utf8');
    // Node-style ".ts" specifiers → the backend's NodeNext ".js" specifiers
    out[name] =
      HEADER(`engine/${name}`) +
      `// source sha256 ${sha256(src)}\n` +
      src.replace(/from '\.\/(\w+)\.ts'/g, "from './$1.js'");
  }
  const engineSrc =
    readFileSync(join(SOURCE, 'engine', 'engine.ts'), 'utf8') +
    readFileSync(join(SOURCE, 'engine', 'types.ts'), 'utf8');
  out['meta.ts'] =
    HEADER('engine/') +
    `/** Fingerprint of the engine source this copy was made from (stored in workload snapshots). */\nexport const ENGINE_SOURCE_SHA256 = '${sha256(engineSrc)}';\n`;
  for (const { file, constant } of EDITIONS) {
    const raw = readFileSync(join(SOURCE, 'data', file), 'utf8');
    const ds = JSON.parse(raw);
    const slim = {
      editionId: ds.editionId,
      riwaya: ds.riwaya,
      tariq: ds.tariq,
      countingSystem: ds.countingSystem,
      totalAyahs: ds.totalAyahs,
      sourceSha256: sha256(raw),
      pdfSha256: ds.source.sha256,
      surahs: ds.surahs.map((s) => ({
        surah: s.surah,
        ayahCount: s.ayahCount,
        status: s.status,
      })),
      pageStarts: ds.pageStarts.map((p) => ({
        page: p.page,
        surah: p.surah,
        ayah: p.ayah,
        status: p.status,
      })),
      eighthStarts: ds.eighthStarts.map((e) => ({
        index: e.index,
        hizb: e.hizb,
        eighth: e.eighth,
        surah: e.surah,
        ayah: e.ayah,
        status: e.status,
      })),
    };
    out[file.replace(/\.json$/, '.data.ts')] =
      HEADER(`data/${file}`) +
      `import type { ReferenceDataset } from './types.js';\n\n` +
      `export const ${constant}: ReferenceDataset & {\n  tariq: string;\n  countingSystem: string;\n  sourceSha256: string;\n  pdfSha256: string;\n} = ${JSON.stringify(slim)};\n`;
  }
  return out;
}

if (process.argv[1] === fileURLToPath(import.meta.url)) {
  mkdirSync(TARGET, { recursive: true });
  for (const [name, content] of Object.entries(render()))
    writeFileSync(join(TARGET, name), content);
  console.log('quran reference synced into', TARGET);
}
